import calendar
from datetime import date

def nth_weekday(year: int, month: int, weekday: int, n: int) -> str:
    if not (0 <= weekday <= 6):
        raise ValueError("weekday must be 0 (Monday) through 6 (Sunday)")
    if n == 0 or n < -1 or n > 5:
        raise ValueError("n must be 1-5 or -1")

    days_in_month = calendar.monthrange(year, month)[1]
    matching_days = [
        day for day in range(1, days_in_month + 1)
        if date(year, month, day).weekday() == weekday
    ]

    if n == -1:
        if not matching_days:
            raise ValueError("No such weekday occurrence in this month")
        chosen_day = matching_days[-1]
    else:
        if n > len(matching_days):
            raise ValueError("No such weekday occurrence in this month")
        chosen_day = matching_days[n - 1]

    return date(year, month, chosen_day).isoformat()


